#!/bin/sh
# AI generated by: Claude Code (claude-opus-5-5)
# Prompt: "Could you create a small tool that would simulate the whole working
# on the parser and semantics, it should have a input field where there would
# be a picker of token from one to send simulated token from lexer. then there
# should be a rendered AST section and block section. Also add some example
# scenarious covering the different parser-semantic scenarious. Do it with
# simple HTML, CSS and typescript if you need that for functionality" +
# "also create a separate branch for it"
# Changes: new file, checks that the simulator still matches src/: every
# scenario is run through the real parser + semantic analysis (C, fed by the
# fake token source of the unit tests) and through engine.js, and the exit
# codes and AST test strings are compared. Needs clang and a JavaScript shell
# with print() (macOS JavaScriptCore by default, override with JS=...).
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../.." && pwd)
JS=${JS:-/System/Library/Frameworks/JavaScriptCore.framework/Versions/Current/Helpers/jsc}
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

"$JS" "$HERE/engine.js" "$HERE/scenarios.js" "$HERE/verify/gen_harness.js" > "$WORK/harness.c"
SRCS=$(ls "$ROOT"/src/*.c | grep -v '/ifj26\.c$')
# shellcheck disable=SC2086
clang -std=gnu17 -w -I"$ROOT/src" -I"$ROOT/tests/unit/helpers" -o "$WORK/harness" "$WORK/harness.c" \
  $SRCS "$ROOT/tests/unit/helpers/fake_tokens.c" "$ROOT/tests/unit/helpers/ast_test_string.c"
"$WORK/harness" 2>/dev/null > "$WORK/c.txt"
"$JS" "$HERE/engine.js" "$HERE/scenarios.js" "$HERE/verify/js_results.js" > "$WORK/js.txt"

if diff -u "$WORK/c.txt" "$WORK/js.txt"; then
  echo "simulator matches src/ on $(grep -c ' E ' "$WORK/c.txt") scenarios"
else
  echo "simulator differs from src/ (- C, + simulator)" >&2
  exit 1
fi
